window.products.push({"id":183817,"name":"BrewDemon 2 Gal. Boysenberry Hard Cider Recipe Kit - Makes a Wicked-Good 5.5% ABV Batch of Craft Brewed Hard Cider","category":"homeandappliances","retail price":29.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/71M3TGreePL._AC_SL1500_.jpg","description":"🍺 CONSISTENT RESULTS - Unlike other kits, our recipes take just minutes to prepare and the results are scary-good! 🍺 NEW ZEALAND RECIPE - BrewDemon hard cider mixes feature apples grown in the fertile orchards of New Zealand, only the finest quality apples are chosen at the height of their ripeness, prepared by master brewers in New Zealand’s famous Speight’s brewery, providing the optimum flavor profiles for world-class hard cider. 🍺 FOCUS ON YOUR RECIPE - Our recipes work best using the BrewDemon 2 gallon conical system, but can be brewed with any 2 gallon system. 🍺 EVERYTHING YOU NEED - This kit includes the ingredients to make this 2 gallon recipe. 🍺 Enjoy great tasting home made hard cider from your kitchen - only with BrewDemon!","images":["https://m.media-amazon.com/images/I/71M3TGreePL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"BrewDemon","source_asin":"B00HYNKPY2","category_path":"Home & Kitchen"},"sku":"BM-183817","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00HYNKPY2","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00HYNKPY2","price_pending":true,"merchant_ready":false});
window.products.push({"id":183818,"name":"jinchan Room Darkening Curtains for Bedroom Living Room Thermal Insulated Linen Textured Window Treatment 2 Panels 84 Inch Heathered Beige","category":"homeandappliances","retail price":25.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/71cG7PO4DiL._AC_SL1500_.jpg","description":"Simple Design: You will find two 38\" wide x 84\" long room darkening curtain panels in package. Light Control: With these room darkening beige panels you get 60% sunlight out for bedtime, 0 TV glare for your favorite game and absolute privacy with all your indoor activity. Energy Smart: These thermal insulated curtains will make a budget noticeable difference, lower your heating & cooling cost by preventing sunlight & draft from getting in. Easy Care: Machine washable in cold water, tumble dry. Quick ironing or steam clean as needed. Size Note: For proper look and fullness, the curtain panels should measure 2-3 times the width of your window/opening.","images":["https://m.media-amazon.com/images/I/71cG7PO4DiL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"jinchan","source_asin":"B09C7NHFKT","category_path":"Home & Kitchen"},"sku":"BM-183818","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B09C7NHFKT","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B09C7NHFKT","price_pending":true,"merchant_ready":false});
